-- Normalize LET Secondary Area of Specialization taxonomy.
-- Generated by scripts/normalize-let-secondary-major-taxonomy.mjs.
-- Rollback: restore question topic_id/status/content columns from public.let_secondary_major_taxonomy_2026_backup, then restore topic slugs/names from the same backup snapshots if needed.
BEGIN;

ALTER TABLE public.questions ADD COLUMN IF NOT EXISTS major text;
ALTER TABLE public.questions ADD COLUMN IF NOT EXISTS major_slug text;
ALTER TABLE public.questions ADD COLUMN IF NOT EXISTS sub_tag text;
ALTER TABLE public.questions ADD COLUMN IF NOT EXISTS sub_tag_slug text;
ALTER TABLE public.questions ADD COLUMN IF NOT EXISTS exam_level text;
ALTER TABLE public.questions ADD COLUMN IF NOT EXISTS exam_area text;
ALTER TABLE public.questions ADD COLUMN IF NOT EXISTS taxonomy_version text;
ALTER TABLE public.questions ADD COLUMN IF NOT EXISTS needs_review boolean NOT NULL DEFAULT false;
ALTER TABLE public.questions ADD COLUMN IF NOT EXISTS review_reason text;

CREATE TABLE IF NOT EXISTS public.let_secondary_major_taxonomy_2026_backup (
  question_id uuid PRIMARY KEY,
  backup_created_at timestamptz NOT NULL DEFAULT now(),
  old_topic_id uuid NOT NULL,
  old_topic_slug text NOT NULL,
  old_topic_name text NOT NULL,
  old_status public.question_status NOT NULL,
  question_snapshot jsonb NOT NULL
);

CREATE TABLE IF NOT EXISTS public.let_secondary_major_taxonomy_2026_manual_review (
  question_id uuid PRIMARY KEY,
  old_topic_slug text NOT NULL,
  suggested_topic_slug text NOT NULL,
  review_reason text NOT NULL,
  stem text NOT NULL,
  source_note text,
  created_at timestamptz NOT NULL DEFAULT now()
);

WITH major_questions AS (
  SELECT q.id, q.topic_id, t.slug AS old_topic_slug, t.name AS old_topic_name, q.status, to_jsonb(q) AS snapshot
  FROM public.questions q
  JOIN public.topics t ON t.id = q.topic_id
  JOIN public.subject_areas sa ON sa.id = t.subject_area_id
  JOIN public.exam_types et ON et.id = sa.exam_type_id AND et.slug = 'let-secondary'
  WHERE sa.slug = 'major'
)
INSERT INTO public.let_secondary_major_taxonomy_2026_backup (question_id, old_topic_id, old_topic_slug, old_topic_name, old_status, question_snapshot)
SELECT id, topic_id, old_topic_slug, old_topic_name, status, snapshot FROM major_questions
ON CONFLICT (question_id) DO NOTHING;

WITH major_sa AS (
  SELECT sa.id
  FROM public.subject_areas sa
  JOIN public.exam_types et ON et.id = sa.exam_type_id
  WHERE et.slug = 'let-secondary' AND sa.slug = 'major'
)
INSERT INTO public.topics (subject_area_id, slug, name, sort_order)
SELECT major_sa.id, seed.slug, seed.name, seed.sort_order
FROM major_sa
CROSS JOIN (VALUES
  ('biological-science', 'Biological Science', 5),
  ('physical-science', 'Physical Science', 6),
  ('science-review-needed', 'Science Review Needed', 100)
) AS seed(slug, name, sort_order)
ON CONFLICT (subject_area_id, slug) DO UPDATE SET
  name = EXCLUDED.name,
  sort_order = EXCLUDED.sort_order;

WITH major_sa AS (
  SELECT sa.id FROM public.subject_areas sa JOIN public.exam_types et ON et.id = sa.exam_type_id
  WHERE et.slug = 'let-secondary' AND sa.slug = 'major'
)
UPDATE public.topics t
SET slug = CASE t.slug
    WHEN 'social-studies' THEN 'social-studies-araling-panlipunan'
    ELSE t.slug
  END,
  name = CASE t.slug
    WHEN 'social-studies' THEN 'Social Studies / Araling Panlipunan'
    WHEN 'mapeh' THEN 'MAPEH'
    WHEN 'tle' THEN 'Technology and Livelihood Education (TLE)'
    ELSE t.name
  END,
  sort_order = CASE t.slug
    WHEN 'english' THEN 1
    WHEN 'mathematics' THEN 2
    WHEN 'filipino' THEN 3
    WHEN 'social-studies' THEN 4
    WHEN 'values-education' THEN 7
    WHEN 'mapeh' THEN 8
    WHEN 'tle' THEN 9
    ELSE t.sort_order
  END
FROM major_sa
WHERE t.subject_area_id = major_sa.id;

WITH major_sa AS (
  SELECT sa.id FROM public.subject_areas sa JOIN public.exam_types et ON et.id = sa.exam_type_id
  WHERE et.slug = 'let-secondary' AND sa.slug = 'major'
)
UPDATE public.topics t
SET sort_order = CASE t.slug
    WHEN 'home-economics' THEN 109
    WHEN 'ict' THEN 110
    WHEN 'industrial-arts' THEN 111
    WHEN 'agriculture-fishery-arts' THEN 112
    WHEN 'tvted' THEN 113
    WHEN 'science' THEN 114
    ELSE t.sort_order
  END,
  name = CASE t.slug
    WHEN 'home-economics' THEN 'Home Economics (Legacy - use TLE)'
    WHEN 'ict' THEN 'ICT (Legacy - use TLE)'
    WHEN 'industrial-arts' THEN 'Industrial Arts (Legacy - use TLE)'
    WHEN 'agriculture-fishery-arts' THEN 'Agriculture & Fishery Arts (Legacy - use TLE)'
    WHEN 'tvted' THEN 'Technical-Vocational Education (Legacy - use TLE)'
    WHEN 'science' THEN 'Science (Legacy - split into Biological/Physical)'
    ELSE t.name
  END
FROM major_sa
WHERE t.subject_area_id = major_sa.id
  AND t.slug IN ('home-economics','ict','industrial-arts','agriculture-fishery-arts','tvted','science');

-- Move 289 question(s) to english.
WITH target_topic AS (
  SELECT t.id
  FROM public.topics t
  JOIN public.subject_areas sa ON sa.id = t.subject_area_id
  JOIN public.exam_types et ON et.id = sa.exam_type_id
  WHERE et.slug = 'let-secondary' AND sa.slug = 'major' AND t.slug = 'english'
)
UPDATE public.questions q
SET topic_id = (SELECT id FROM target_topic),
    major = 'English',
    major_slug = 'english',
    exam_level = 'LET Secondary',
    exam_area = 'Area of Specialization',
    taxonomy_version = 'LET_SECONDARY_MAJOR_TAXONOMY_2026',
    needs_review = false,
    review_reason = NULL,
    tags = array(SELECT DISTINCT tag FROM unnest(coalesce(q.tags, '{}') || ARRAY['let-secondary-major-taxonomy-2026', 'major:english']) AS tag),
    updated_at = now()
