-- Move 45 question(s) to mathematics.
WITH target_topic AS (
  SELECT t.id
  FROM public.topics t
  JOIN public.subject_areas sa ON sa.id = t.subject_area_id
  JOIN public.exam_types et ON et.id = sa.exam_type_id
  WHERE et.slug = 'let-secondary' AND sa.slug = 'major' AND t.slug = 'mathematics'
)
UPDATE public.questions q
SET topic_id = (SELECT id FROM target_topic),
    major = 'Mathematics',
    major_slug = 'mathematics',
    exam_level = 'LET Secondary',
    exam_area = 'Area of Specialization',
    taxonomy_version = 'LET_SECONDARY_MAJOR_TAXONOMY_2026',
    needs_review = false,
    review_reason = NULL,
    tags = array(SELECT DISTINCT tag FROM unnest(coalesce(q.tags, '{}') || ARRAY['let-secondary-major-taxonomy-2026', 'major:mathematics']) AS tag),
    updated_at = now()
WHERE q.id = ANY(ARRAY['9e0077ca-be16-4be6-9cbe-5b49980b0a2b'::uuid, 'dbd11c67-e81f-4b6b-938c-55cde84843f2'::uuid, 'e971d09a-7488-4dfd-a441-d8a9a0d68859'::uuid, 'f92481a3-6b86-4e43-8bb1-622443e14471'::uuid, '5c111706-641c-4fe7-8ec6-0ddaa447123c'::uuid, '18d61829-ee7f-4ab6-8350-80b0127f0ca7'::uuid, 'd70d9368-d9f1-44ac-83cf-3d9ca1f68112'::uuid, 'e0f83c38-f12a-4800-8531-515e7c6c7a02'::uuid, 'c8c94f6a-e1ac-4c28-aa71-79993dcc174c'::uuid, '2dd78edf-ac3c-4c47-85f3-f865dc4427f9'::uuid, '042d0958-8d55-438b-93cf-bfa981228ac7'::uuid, '2bd88d5c-f3c2-449d-9b90-4ac5d462ecc1'::uuid, 'b6ca0de5-6e01-4796-a16d-916115215ed5'::uuid, '1a01d339-3ecb-43f9-8879-17b6a7f13d2b'::uuid, '09040382-be14-49c3-a0c4-98ecd13b3178'::uuid, '08219045-9a6b-41da-9f70-264b871c4de7'::uuid, 'd3fbaeeb-3016-4347-870f-96e595614ba5'::uuid, '5cd45d7f-d2d8-4a2e-aa15-3aff62e30ef3'::uuid, '27e627b8-cace-47eb-9c6e-bf3e2c191379'::uuid, 'c25f0a6f-51dd-4039-82bc-397c496f727d'::uuid, 'eb7e3cfd-275e-4cbd-b7b0-2d64fd75764d'::uuid, '2384cec2-0474-47b3-ad43-08d44fa89e5f'::uuid, 'c47ddb44-d286-4f69-a941-2e43eac2f09f'::uuid, '5bf55e1c-54d7-4985-be0b-5f576566f5d6'::uuid, '87cace7e-6eff-45e5-af2d-583e326d2728'::uuid, '3a7e5407-4756-4028-9e3a-fa6260189210'::uuid, 'dba42c86-2171-487e-b6f7-35c7bc0995e3'::uuid, 'a479e15d-4757-47c7-aae2-719f74201572'::uuid, 'b16315a3-99a4-457e-be5c-506dfd1aa436'::uuid, '684f3a61-3e18-4328-868d-cb4002fb3824'::uuid, '0c57e523-8591-4ff3-a551-9d0c100ca451'::uuid, '2dc24635-d954-4dfd-a11e-50d767333eaa'::uuid, 'a4f976e1-b8e0-415e-ae73-62083c334193'::uuid, '744e377e-3018-4790-a1b5-cb66fef35c84'::uuid, '3c2afa9e-0e0c-4e8e-b62f-278a2997338d'::uuid, 'ffb6971d-3054-4670-a221-cb3b68ca7381'::uuid, '0901222a-ef4a-481e-adfd-efac6405d9af'::uuid, '2a33f494-6f3e-4f18-8b7f-aeabdc307337'::uuid, '1149d474-4a91-492a-8442-7512bf8d88aa'::uuid, '43f8212f-63b6-44ec-865a-02e7fea59442'::uuid, 'aacd99d2-3e92-4b73-9d10-aebf35c32540'::uuid, 'c58ad1a9-b604-4799-9565-c2ac5a3bee66'::uuid, 'e660b97f-3f73-4b3d-a317-22336d0436f1'::uuid,