-- Move 499 question(s) to filipino.
WITH target_topic AS (
  SELECT t.id
  FROM public.topics t
  JOIN public.subject_areas sa ON sa.id = t.subject_area_id
  JOIN public.exam_types et ON et.id = sa.exam_type_id
  WHERE et.slug = 'let-secondary' AND sa.slug = 'major' AND t.slug = 'filipino'
)
UPDATE public.questions q
SET topic_id = (SELECT id FROM target_topic),
    major = 'Filipino',
    major_slug = 'filipino',
    exam_level = 'LET Secondary',
    exam_area = 'Area of Specialization',
