-- Move 430 question(s) to physical-science.
WITH target_topic AS (
  SELECT t.id
  FROM public.topics t
  JOIN public.subject_areas sa ON sa.id = t.subject_area_id
  JOIN public.exam_types et ON et.id = sa.exam_type_id
  WHERE et.slug = 'let-secondary' AND sa.slug = 'major' AND t.slug = 'physical-science'
)
UPDATE public.questions q
SET topic_id = (SELECT id FROM target_topic),
    major = 'Physical Science',
    major_slug = 'physical-science',
    exam_level = 'LET Secondary',
    exam_area = 'Area of Specialization',
    taxonomy_version = 'LET_SECONDARY_MAJOR_TAXONOMY_2026',
    needs_review = false,
    review_reason = NULL,
    tags = array(SELECT DISTINCT tag FROM unnest(coalesce(q.tags, '{}') || ARRAY['let-secondary-major-taxonomy-2026', 'major:physical-science']) AS tag),
