-- Move 523 question(s) to tle.
WITH target_topic AS (
  SELECT t.id
  FROM public.topics t
  JOIN public.subject_areas sa ON sa.id = t.subject_area_id
  JOIN public.exam_types et ON et.id = sa.exam_type_id
  WHERE et.slug = 'let-secondary' AND sa.slug = 'major' AND t.slug = 'tle'
)
UPDATE public.questions q
SET topic_id = (SELECT id FROM target_topic),
    major = 'Technology and Livelihood Education (TLE)',
    major_slug = 'tle',
    exam_level = 'LET Secondary',
    exam_area = 'Area of Specialization',
    taxonomy_version = 'LET_SECONDARY_MAJOR_TAXONOMY_2026',
    needs_review = false,
    review_reason = NULL,
    tags = array(SELECT DISTINCT tag FROM unnest(coalesce(q.tags, '{}') || ARRAY['let-secondary-major-taxonomy-2026', 'major:tle']) AS tag),
    updated_at = now()
WHERE q.id = ANY(ARRAY['11979485-f9d5-4260-9b5a-c2c8fd602862'::uuid, '32edde40-b2b0-406c-ae8b-c109dc000332'::uuid, '575e60a7-c669-4a01-950a-5f4eb8d379ea'::uuid, 'd80d888a-e90c-4f6e-b99e-5e31222ead24'::uuid, 'd70f226b-7772-4b21-869a-4679a3e16ff9'::uuid, '271569da-c580-41f5-b98a-9b83c79b490c'::uuid, '479b2dee-571e-4ed5-b6f7-b9b7a83a4893'::uuid, '4b1840ce-ec4f-41fe-acbb-6d625499bc99'::uuid, '1a703fc8-3c0f-44c7-9aea-facc841690a5'::uuid, 'e4546bcf-dd0f-4a8f-ba37-a28c4eda93f5'::uuid, '63644ae5-9f60-49de-a52e-b2bc0388b124'::uuid, 'a69499fc-ac71-47d0-8462-400664083f23'::uuid, 'be345372-8113-4202-b82a-fd914bd2c181'::uuid, '36e0d94d-01e9-4654-b870-928ef2bad2da'::uuid, '9b1042da-11e4-44b8-98f5-3f0150fbbf77'::uuid, 'c164f5a1-6140-4529-903d-bd8a0f40d695'::uuid, '5f6a0045-03e3-437b-abae-d1b0f76f9b1f'::uuid, 'db9aabd9-993e-45fa-a08e-91e813c88dab'::uuid, '7c9cae80-e0d7-4b23-90fd-e00271dbc05f'::uuid, 'e611ac1e-2d26-4945-a9b0-e7d9e8fe3aeb'::uuid, '23110f9a-ed36-4375-9190-dcfe416b233c'::uuid, 'ffe29677-a2c8-4566-b4bf-96c68e01f038'::uuid, '99037a33-7680-4809-a015-afd397086cb6'::uuid, '31edaf3f-aafb-4e89-80f5-ee6ae1d4ed16'::uuid, '85bf99b6-1d9a-4716-baa7-238563a1240e'::uuid, 'f11acf9a-e3fb-4262-b925-adefd4945b32'::uuid, '57a64bc7-9aa8-4ca0-9ed7-9f1527058946'::uuid, 'f845c12d-5c36-495e-9064-411af1daa41c'::uuid, '1b006388-e0eb-439e-b8ab-31d07e729ccc'::uuid, '331d3729-99e2-4e01-b6fc-a8bc3e9f0a56'::uuid, '60631c03-fd7b-42fd-b494-621b811703dd'::uuid, '9397e7fe-cdf0-4020-a152-f673c778a950'::uuid, 'e35bbb37-4f30-4068-ae1e-96ddb143b992'::uuid, '3b15e64f-ff78-4e78-ae53-7e301388cf62'::uuid, '5317cca1-e4fa-4942-89b6-0265d9063595'::uuid, 'd5ef66e1-c62a-4c2a-a764-69ff733f9530'::uuid, '66e7f2cd-acf5-4953-8052-0e02e64c02b3'::uuid, '8b08047e-99cf-4482-9ce2-01fdb07eaea0'::uuid, 'a2d50f18-c612-49ee-b052-bc11c08bdc30'::uuid, '364add2c-f8ac-4e02-b4bb-ec4a084ac080'::uuid, '6cf9149b-13d2-48a8-ace4-2fd7ace5d0f5'::uuid, '6ded2742-7a52-4abc-b940-c49b1b864bba'::uuid, '3c92753b-c540-47ae-8bb0-92bc2cf5f5fa'::uuid,