-- Move 31 question(s) to science-review-needed.
WITH target_topic AS (
  SELECT t.id
  FROM public.topics t
  JOIN public.subject_areas sa ON sa.id = t.subject_area_id
  JOIN public.exam_types et ON et.id = sa.exam_type_id
  WHERE et.slug = 'let-secondary' AND sa.slug = 'major' AND t.slug = 'science-review-needed'
)
UPDATE public.questions q
SET topic_id = (SELECT id FROM target_topic),
    major = 'Science Review Needed',
    major_slug = 'science-review-needed',
    exam_level = 'LET Secondary',
    exam_area = 'Area of Specialization',
    taxonomy_version = 'LET_SECONDARY_MAJOR_TAXONOMY_2026',
    needs_review = true,
    review_reason = 'Science major could not be confidently split into Biological Science or Physical Science.',
    tags = array(SELECT DISTINCT tag FROM unnest(coalesce(q.tags, '{}') || ARRAY['let-secondary-major-taxonomy-2026', 'major:science-review-needed']) AS tag),
    updated_at = now()
WHERE q.id = ANY(ARRAY['8411da33-2cfa-4d75-872f-9d289beb3cc0'::uuid, 'd6d25709-cf4c-4c5c-9fbb-ecda2bc45db4'::uuid, 'b15a6e31-0b37-4356-a884-46b84a6c1514'::uuid, '2f13b050-4dae-4890-9a69-a7692946a707'::uuid, '6825858f-a0b3-4de2-b9bc-ab2c851e26b9'::uuid, '9804a94a-024c-4412-b2a2-da04b59333a1'::uuid, 'd11b9840-f298-43aa-8775-3b35db736105'::uuid, 'cbc2391c-d4c8-438d-9898-1a5b9a943d95'::uuid, '302edb75-4181-4092-9b75-26181298c8a3'::uuid, 'd6d4bebb-0376-47ed-8790-a7f07f5391d5'::uuid, '98daa76f-ef04-403e-943a-62b127a8a879'::uuid, '6dd59135-5b91-4a83-bfc5-fa0640b74de6'::uuid, '7225f263-f40f-4703-be48-aba0b0786923'::uuid, 'e5f10bd4-961f-429e-a0b9-50474aa0864d'::uuid, '2f1a8824-4a05-4fd0-b712-fc04814c05d8'::uuid, '18cd4527-06bc-4700-9d04-1dd4a19568ce'::uuid, '82eaf667-85ef-4173-95c9-a23aa215eab2'::uuid, 'ebb2d171-3c24-429f-bd8c-2b9b10d0b34b'::uuid, '9aed0a7b-f6ab-4f74-b616-4af1cf6f443a'::uuid, 'c9261e6a-c257-4659-a5ae-b798e0e06300'::uuid, '55b87854-0e1c-4135-9ac7-f3a573f3a5bb'::uuid, '4d5f27e7-bf6e-49f3-b18f-4f3b1231fe73'::uuid, '6c99f102-c3fe-4242-9bea-2bcb8a074d28'::uuid, 'e8051d59-e2ca-4238-9b8c-d226507c4922'::uuid, 'ce038b1a-97a1-4901-98a8-954347663094'::uuid, '26f023e9-45c7-4675-bc9e-554a9622ebf0'::uuid, '7cba90d2-8e0a-4b54-a6c8-8842b3671bf5'::uuid, '74da5a62-f278-41d1-be97-86443c6cd7f6'::uuid, 'fc44cc4b-6d26-47d6-a259-2c975f05665f'::uuid, '26fcf3d3-d27d-4393-bd7b-291c88e59e84'::uuid, 'd7858dc5-8bb7-4f36-a788-b6a21aca3db9'::uuid]);

